rawScripts.raw:
//发射[参数：MC名称，param]
/*
params 参数 {
	x:Number(速度X)|{start:Number(开始速度),add:Number(加速度),max:Number(最大速度),hit:Number(攻击到速度)} , 
	y:Number(速度Y)|{start:Number(开始速度),add:Number(加速度),max:Number(最大速度),hit:Number(攻击到速度)} , 
	hold:int(持续帧数) ,
	hits:int(攻击次数)
}
*/
parent.$mc_ctrler.fire("zh1atm",{x:{start:20},hold:60,hits:1});

//发射[参数：MC名称，param]
/*
params 参数 {
	x:Number(速度X)|{start:Number(开始速度),add:Number(加速度),max:Number(最大速度),hit:Number(攻击到速度)} , 
	y:Number(速度Y)|{start:Number(开始速度),add:Number(加速度),max:Number(最大速度),hit:Number(攻击到速度)} , 
	hold:int(持续帧数) ,
	hits:int(攻击次数)
}
*/
parent.$mc_ctrler.fire("zh11atm",{x:{start:20},hold:60,hits:1});

//加入攻击对象[参数：MC名称，params]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("zh2mc",{x:{moveToTarget:true,offset:0,range:[50,500]}});

//加入攻击对象[参数：MC名称，params]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("zh22mc",{applyG:false});
